@router.post('/api/documents/batch-archive')
def create_batch_document_archive(
    payload: BatchArchiveRequest,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user)
):
    docs = db.query(Document).filter(Document.id.in_(payload.document_ids), Document.owner_id == user.id).all()
    if not docs:
        raise HTTPException(status_code=404, detail="No matching documents found")

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        for doc in docs:
            if os.path.exists(doc.file_path):
                zf.write(doc.file_path, arcname=doc.filename)

    zip_buffer.seek(0)
    return StreamingResponse(
        zip_buffer,
        media_type="application/zip",
        headers={"Content-Disposition": "attachment; filename=documents.zip"}
    )
